<template><q-page class="q-pa-lg" v-if="leave"><q-btn flat icon="arrow_back" label="Back" @click="router.back()"/><q-card flat bordered class="q-mt-md q-pa-lg"><div class="page-title">{{leave.leave_type}}</div><q-badge class="q-mt-sm" :color="color(leave.status)" :label="leave.status"/><div class="row q-col-gutter-lg q-mt-md"><div class="col-6 col-md-3"><b>Employee</b><div>{{leave.employee_name}}</div></div><div class="col-6 col-md-3"><b>Dates</b><div>{{leave.start_date}} — {{leave.end_date}}</div></div><div class="col-6 col-md-3"><b>Duration</b><div>{{leave.days}} day(s)</div></div><div class="col-6 col-md-3"><b>Reviewed by</b><div>{{leave.reviewer_name||'Not reviewed'}}</div></div></div><div class="q-mt-lg"><b>Reason</b><p class="muted">{{leave.reason||'No reason provided.'}}</p></div><div v-if="leave.rejection_reason"><b>Rejection reason</b><p class="text-negative">{{leave.rejection_reason}}</p></div></q-card></q-page></template><script setup>import{ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import api from'../services/api';const route=useRoute(),router=useRouter(),leave=ref(null);onMounted(async()=>{try{leave.value=(await api.get(`/leaves/${route.params.id}`)).data.data}catch{router.push('/')}});const color=x=>x==='Approved'?'positive':x==='Rejected'?'negative':x==='Cancelled'?'grey-6':'orange';</script>
